def validate_request(value: object) -> InputValidator:
    """Validate without advancing input or inserting defaults; paths use canonical schema names."""
    errors: list[str] = []
    _validate64(value, "request", errors)
    if errors:
        raise TypeError("Invalid deepgram TTS request:\n" + "\n".join(errors))
    _validate70(value, "request", errors)
    accepts0 = not errors
    errors.clear()
    def validate_input(item: object, field: str = "text") -> None:
        errors: list[str] = []
        if accepts0:
            before = len(errors)
            _validate69(item, "text item", errors)
            if len(errors) == before:
                return
        if not errors:
            errors.append("text item: streaming input is not supported by this request")
        raise TypeError("Invalid deepgram TTS input item:\n" + "\n".join(errors))
    return validate_input
